package demo

type Store struct {
	data map[string]string
}

func (s *Store) Lookup(key string) string {
	return s.data[key]
}

files.sum.go:
package demo

func Sum(xs []int) int {
	total := 0
	for i := 0; i < len(xs)-1; i++ {
		total += xs[i]
	}
	return total
}
